LAYOUTS = (('layout_10jul.json', 1, 24), ('layout_1011jul.json', 1, 12), ('layout_12jul.json', 13, 24))


def main():
    for t in range(1, 25):
        for D in (SOV, SOV_RU, GER, GER_RU): assert t in D and len(D[t]) < 620, (t, len(D.get(t, '')))
    root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'docs', 'm11_prokhorovka')
    for name, a, b in LAYOUTS:
        p = os.path.join(root, name); L = json.load(open(p, encoding='utf-8'))
        assert len(L['frames']) == b - a + 1, (name, len(L['frames']))
        for i, fr in enumerate(L['frames']): fr['brief'] = 'brief_%02d' % (a + i)
        br = L['briefing']
        for key, D in (('briefs', SOV), ('briefs_rus', SOV_RU), ('briefs_ger', GER), ('briefs_ger_rus', GER_RU)):
            br[key] = {'brief_%02d' % t: D[t] for t in range(a, b + 1)}
        json.dump(L, open(p, 'w', encoding='utf-8', newline='\n'), ensure_ascii=False, indent=1)
        print(name, 'turns %d-%d' % (a, b))


if __name__ == '__main__':
    main()
